static int world_model_lookup(int pc)
{
    int lo = 0, hi = WORLD_MODEL_SEGS - 1;

    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (pc < world_model_seg[mid].lo)
            hi = mid - 1;
        else if (pc > world_model_seg[mid].hi)
            lo = mid + 1;
        else
            return pc + world_model_seg[mid].delta;
    }
    return -1;
}
